INSERT INTO rules (rule_id, name, description, enabled, configuration_json) VALUES ('R001', 'Unusually Large Transfer', 'Compares transaction amount against customer established distribution (percentiles and typical amounts).', 1, '{"percentile_threshold": 95.0, "multiplier_threshold": 5.0, "min_material_amount": 150000.0}') ON CONFLICT (rule_id) DO NOTHING;
INSERT INTO rules (rule_id, name, description, enabled, configuration_json) VALUES ('R002', 'New Payee Burst', 'Identifies rapid multiple transactions sent to a newly added payee within a short time window.', 1, '{"time_window_minutes": 60, "min_transactions": 3, "min_total_amount": 20000.0}') ON CONFLICT (rule_id) DO NOTHING;
INSERT INTO rules (rule_id, name, description, enabled, configuration_json) VALUES ('R003', 'Odd-Hours Activity', 'Flags activity during odd hours (00:00 - 05:00) when customer history shows little to no historical activity.', 1, '{"start_hour": 0, "end_hour": 5, "max_historical_rate": 0.03, "min_odd_transactions": 1}') ON CONFLICT (rule_id) DO NOTHING;
INSERT INTO rules (rule_id, name, description, enabled, configuration_json) VALUES ('R004', 'Behavioural Pattern Break', 'Flags significant structural shifts in channel distribution, transaction velocity, or frequency in recent activity.', 1, '{"recent_window_days": 10, "min_channel_deviation_pct": 25.0, "min_recent_txns": 4}') ON CONFLICT (rule_id) DO NOTHING;
INSERT INTO customers (customer_id, name, profile, expected_result, created_at) VALUES ('CUST-001', 'Priya Sharma', 'Normal Behavioral Profile (Salary, groceries, utilities, typical daytime UPI/card usage)', 'NO ATTENTION REQUIRED', '2026-01-01T00:00:00Z') ON CONFLICT (customer_id) DO NOTHING;
INSERT INTO customers (customer_id, name, profile, expected_result, created_at) VALUES ('CUST-002', 'Arjun Patel', 'Large Transfer Scenario (Normal ₹1k-₹10k range with anomalous ₹4,80,000 transfer)', 'ATTENTION REQUIRED (R001: Unusually Large Transfer)', '2026-01-01T00:00:00Z') ON CONFLICT (customer_id) DO NOTHING;
INSERT INTO customers (customer_id, name, profile, expected_result, created_at) VALUES ('CUST-003', 'Ananya Roy', 'New Payee Rapid Burst Scenario (New payee XYZ Services with rapid burst within 47 minutes)', 'ATTENTION REQUIRED (R002: New Payee Burst)', '2026-01-01T00:00:00Z') ON CONFLICT (customer_id) DO NOTHING;
INSERT INTO customers (customer_id, name, profile, expected_result, created_at) VALUES ('CUST-004', 'Vikram Malhotra', 'Odd-Hours Activity Scenario (Strict historical daytime activity with 02:00-04:00 night transactions)', 'ATTENTION REQUIRED (R003: Odd-Hours Activity)', '2026-01-01T00:00:00Z') ON CONFLICT (customer_id) DO NOTHING;
INSERT INTO customers (customer_id, name, profile, expected_result, created_at) VALUES ('CUST-005', 'Rajesh Verma', 'Complex Multi-Vector Case (Large transfer + new payee burst + odd-hours + channel shift)', 'ATTENTION REQUIRED (R001, R002, R003, R004)', '2026-01-01T00:00:00Z') ON CONFLICT (customer_id) DO NOTHING;
